let out = {};
try { out = JSON.parse($json.choices[0].message.content); }
catch (e) { out = { intent:'unknown', category:'unknown', purpose:'', summary:'', parse_error:String(e) }; }
return { json: out };

const intent = $('Parse Intent').item.json;
const inp = $('Normalize Input').item.json;

// ----- EDIT: base risk score per category (0-100) -----
const CATEGORY_SCORE = {
  biometric:90, credit:80, employment:80, law_enforcement:90, medical:75,
  finance:70, content:30, search:20, general:25, unknown:40
};
const cat = (intent.category || 'unknown').toLowerCase();
let score = (CATEGORY_SCORE[cat] !== undefined) ? CATEGORY_SCORE[cat] : 40;

const HIGH_IMPACT = ['delete','transfer','pay','send','deploy','email','post','execute'];
if (HIGH_IMPACT.includes((inp.action||'').toLowerCase())) score += 15;
if (inp.confidence < 0.6) score += 10;
score = Math.max(0, Math.min(100, score));

let tier = 'minimal';
if (score >= 80) tier = 'high';
else if (score >= 50) tier = 'limited';

// EU AI Act Art. 5 - prohibited uses
const UNACCEPTABLE = ['social_scoring','manipulation'];
if (UNACCEPTABLE.includes(cat)) { tier = 'unacceptable'; score = 100; }

return { json: { risk_score: score, risk_tier: tier, risk_reasons: [
  `category ${cat}`, `action ${inp.action}`, `confidence ${inp.confidence}`
] } };

const r = $json || {};
let items = r.results || r.points || r.matches || r.hits || [];
if (!Array.isArray(items)) items = [];
const policyText = items.map((x,i) => {
  const t = x.text || (x.payload && x.payload.text) || x.content || JSON.stringify(x);
  const s = x.source || (x.payload && x.payload.source) || x.framework || 'policy';
  return `[${i+1}] (${s}) ${t}`;
}).join('\n');
const sources = items.map(x => x.source || (x.payload && x.payload.source) || 'policy');
return { json: { policyText: policyText || 'No policy retrieved.', sources } };

// Parse Compliance — LLM extracts obligations; CODE decides the verdict.
let ext = { obligations: [], articles: [] };
try {
  ext = JSON.parse($json.choices[0].message.content);
} catch (e) {
  return { json: {
    compliant: false,
    verdict: 'human_review',
    reasoning: 'Compliance extraction could not be parsed: ' + String(e),
    articles: [],
    obligations: []
  } };
}

const obligations = Array.isArray(ext.obligations) ? ext.obligations : [];
let parts_noOblig = '';

const notMet  = obligations.filter(o => o && o.status === 'not_met');
const unclear = obligations.filter(o => o && o.status === 'unclear');
const met     = obligations.filter(o => o && o.status === 'met');

let compliant;
let verdict;

if (notMet.length > 0) {
  compliant = false;
  verdict = 'non_compliant';
} else if (unclear.length > 0) {
  compliant = false;
  verdict = 'human_review';
} else if (obligations.length === 0) {
  const tier = $('Risk Classification').item.json.risk_tier;
  if (tier === 'high' || tier === 'unacceptable') {
    compliant = false;
    verdict = 'human_review';
    parts_noOblig = 'No policy obligation was retrieved for a ' + tier + '-risk action; escalating (policy gap).';
  } else {
    compliant = true;
    verdict = 'compliant';
    parts_noOblig = 'No applicable policy obligation found; permitted at ' + tier + ' risk tier.';
  }
} else {
  compliant = true;
  verdict = 'compliant';
}

const parts = [];
notMet.forEach(o => parts.push('NOT MET [' + (o.article||'?') + ']: ' + (o.requirement||'') + ' — ' + (o.justification||'')));
unclear.forEach(o => parts.push('UNCLEAR [' + (o.article||'?') + ']: ' + (o.requirement||'') + ' — ' + (o.justification||'')));
if (parts.length === 0 && met.length > 0) parts.push('All ' + met.length + ' policy obligation(s) met.');
if (obligations.length === 0) parts.push(parts_noOblig);

const articles = Array.isArray(ext.articles) ? ext.articles : [];
obligations.forEach(o => { if (o && o.article) articles.push(o.article); });

return { json: {
  compliant,
  reasoning: parts.join(' | '),
  articles: Array.from(new Set(articles)),
  verdict,
  obligations
} };

const inp = $('Normalize Input').item.json;
const text = (inp.request || '') + ' ' + JSON.stringify(inp.tool_args || {});
// ----- EDIT: injection / jailbreak patterns -----
const INJECTION = [/ignore (all |the )?(previous |prior )?instructions/i, /system prompt/i,
  /disregard (the |all )?/i, /jailbreak/i, /developer mode/i, /exfiltrate/i];
const flags = [];
INJECTION.forEach(rx => { if (rx.test(text)) flags.push('possible prompt injection ('+rx+')'); });
if (inp.tool && inp.allowed_tools.length && !inp.allowed_tools.includes(inp.tool)) {
  flags.push(`tool '${inp.tool}' not on allow-list`);
}
// ----- EDIT: dangerous tokens in tool args -----
const DANGEROUS = ['rm -rf','drop table','; delete','sudo ','curl http'];
DANGEROUS.forEach(d => { if (text.toLowerCase().includes(d)) flags.push('dangerous token: '+d); });
return { json: { security_pass: flags.length === 0, security_flags: flags } };

const inp = $('Normalize Input').item.json;
const text = (inp.request || '') + ' ' + JSON.stringify(inp.tool_args || {});
// ----- EDIT: PII patterns -----
const PII = {
  email: /[\w.+-]+@[\w-]+\.[\w.-]+/g,
  phone: /\b\+?\d[\d\s-]{8,}\d\b/g,
  card:  /\b(?:\d[ -]*?){13,16}\b/g,
  ni:    /\b[A-Z]{2}\d{6}[A-Z]\b/g
};
const found = {};
for (const k in PII) { const m = text.match(PII[k]); if (m) found[k] = m.length; }
return { json: { privacy_pass: Object.keys(found).length === 0, pii_found: found } };

const inp = $('Normalize Input').item.json;
const reasons = [];
let pass = true;
// ----- EDIT: which actions require a human -----
const HIGH_IMPACT = ['delete','transfer','pay','send','deploy','post','execute'];
if (HIGH_IMPACT.includes((inp.action||'').toLowerCase()) && !inp.human_in_loop) {
  pass = false; reasons.push(`action '${inp.action}' requires human oversight (EU AI Act Art. 14)`);
}
if (!inp.disclosed) { reasons.push('AI interaction not disclosed to user (EU AI Act Art. 50)'); }
return { json: { permission_pass: pass, permission_reasons: reasons } };

const risk = $('Risk Classification').item.json;
const comp = $('Parse Compliance').item.json;
const sec  = $('Security Check').item.json;
const priv = $('Privacy Check').item.json;
const perm = $('Permission Verification').item.json;
const intent = $('Parse Intent').item.json;
const inp  = $('Normalize Input').item.json;
const dh   = ($('DataHub Enrichment').item?.json?.datahub_context) || { resolved: false, note: 'no datahub_context' };
const reasons = [];
let decision = 'approve';
let risk_score = risk.risk_score;
let risk_tier  = risk.risk_tier;
const risk_reasons = Array.isArray(risk.risk_reasons) ? risk.risk_reasons.slice() : [];
const HIGH_IMPACT = ['delete','transfer','pay','send','deploy','post','execute'];
const isHighImpact = HIGH_IMPACT.includes((inp.action||'').toLowerCase());
if (isHighImpact && risk_tier !== 'unacceptable') {
  if (risk_score < 55) {
    risk_score = 55;
    risk_reasons.push("high-impact action '" + inp.action + "' raised residual risk to the limited tier");
  }
  if (risk_score >= 80) risk_tier = 'high';
  else if (risk_score >= 50) risk_tier = 'limited';
}

// ---- DataHub metadata-aware escalation ----
let dh_escalate_human = false;
const DOWNSTREAM_THRESHOLD = 5;

if (isHighImpact) {
  if (dh.resolved === true) {
    const cls = (dh.classification || '').toUpperCase();
    if (cls === 'PII') {
      if (risk_score < 80) risk_score = 80;
      risk_tier = 'high';
      dh_escalate_human = true;
      risk_reasons.push("DataHub: target '" + dh.dataset + "' is classified PII (owner: " + (dh.owner||'unknown') + ") — GDPR-regulated personal data");
    } else if (cls === 'CONFIDENTIAL') {
      if (risk_score < 70) risk_score = 70;
      if (risk_score >= 80) risk_tier = 'high'; else risk_tier = 'limited';
      dh_escalate_human = true;
      risk_reasons.push("DataHub: target '" + dh.dataset + "' is Confidential business data (owner: " + (dh.owner||'unknown') + ")");
    }
    const dc = (typeof dh.downstream_count === 'number') ? dh.downstream_count : 0;
    if (dc >= DOWNSTREAM_THRESHOLD) {
      if (risk_score < 80) risk_score = 80;
      risk_tier = 'high';
      dh_escalate_human = true;
      risk_reasons.push("DataHub: high blast radius — " + dc + " downstream datasets depend on '" + dh.dataset + "'");
    }
  } else {
    dh_escalate_human = true;
    risk_reasons.push("DataHub: could not resolve target metadata (" + (dh.note||'unresolved') + ") — treating as elevated risk");
  }
}
// ---- end DataHub block ----

// ---- Modular policy summary (computed inline, per-item) ----
const policyAgg = (() => {
  const RANK = { approve: 0, human_review: 1, deny: 2 };
  const nameByRank = { 0: 'approve', 1: 'human_review', 2: 'deny' };
  const ds = dh.dataset || 'unknown';
  const cls = (dh.classification || 'UNKNOWN').toUpperCase();
  const results = [];
  // classification policy
  let cv = 'approve', cr = '';
  if (cls === 'PII') { cv = 'deny'; cr = "Classification Policy: '" + ds + "' is PII (personal data) — blocked."; }
  else if (cls === 'CONFIDENTIAL') { cv = 'human_review'; cr = "Classification Policy: '" + ds + "' is Confidential — needs a human to review."; }
  else if (cls === 'INTERNAL') { cv = 'approve'; cr = "Classification Policy: '" + ds + "' is Internal — allowed."; }
  else if (cls === 'PUBLIC') { cv = 'approve'; cr = "Classification Policy: '" + ds + "' is Public — allowed."; }
  else { cv = 'human_review'; cr = "Classification Policy: classification is UNKNOWN — needs a human to review."; }
  results.push({ policy: 'classification', verdict: cv, reason: cr });
  // lineage policy
  const dc = (typeof dh.downstream_count === 'number') ? dh.downstream_count : 0;
  let lv = 'approve', lr = '';
  if (dc >= 50) { lv = 'deny'; lr = "Lineage Policy: '" + ds + "' has " + dc + " downstream tables — huge blast radius, blocked."; }
  else if (dc >= 5) { lv = 'human_review'; lr = "Lineage Policy: '" + ds + "' has " + dc + " downstream tables — needs a human to review."; }
  else { lv = 'approve'; lr = "Lineage Policy: '" + ds + "' has only " + dc + " downstream tables — low blast radius."; }
  results.push({ policy: 'lineage', verdict: lv, reason: lr });
  let worst = 0;
  for (const r of results) worst = Math.max(worst, RANK[r.verdict] || 0);
  return { source: 'policy_aggregator', final_verdict: nameByRank[worst], policy_results: results, reasons: results.map(r => r.reason) };
})();
// ---- end modular policy summary ----

if (risk_tier === 'unacceptable') { decision = 'deny'; reasons.push('Unacceptable-risk use (EU AI Act Art. 5).'); }
if (sec.security_pass === false)  { decision = 'deny'; reasons.push('Security check failed: ' + (sec.security_flags||[]).join('; ')); }
if (comp.compliant === false)     { decision = 'deny'; reasons.push('Non-compliant: ' + (comp.reasoning || '')); }
if (priv.privacy_pass === false)  { decision = 'deny'; reasons.push('Personal data present in request/arguments: ' + JSON.stringify(priv.pii_found)); }
if (decision !== 'deny') {
  if (perm.permission_pass === false) { decision = 'human_review'; (perm.permission_reasons||[]).forEach(r => reasons.push(r)); }
  else if (risk_tier === 'high') { decision = 'human_review'; reasons.push('High-risk tier requires human review (EU AI Act Art. 14).'); }
  else if (dh_escalate_human) { decision = 'human_review'; reasons.push('DataHub metadata context requires human review.'); }
  else if (inp.confidence < 0.6) { decision = 'human_review'; reasons.push('Low model confidence.'); }
}
if (decision === 'approve') reasons.push('All control checks passed.');

// ---- Policy Aggregator override (strictest wins) ----
{
  const RANK = { approve: 0, human_review: 1, deny: 2 };
  const aggV = String(policyAgg.final_verdict).toLowerCase();
  const curR = (decision in RANK) ? RANK[decision] : 0;
  const aggR = (aggV in RANK) ? RANK[aggV] : 0;
  if (aggR > curR) {
    decision = aggV;
    reasons.push("Policy Aggregator override: escalated to '" + aggV + "' by modular policy checks.");
    (policyAgg.reasons || []).forEach(r => reasons.push("Policy → " + r));
  }
}
// ---- end override ----

const articles = new Set();
(comp.articles || []).forEach(a => { const s = String(a).trim(); if (/^Article\s*\d+/i.test(s)) articles.add(s); });
const artRe = /(?:Article|Art\.?)\s*(\d+)/gi;
reasons.forEach(r => { let m; while ((m = artRe.exec(String(r))) !== null) articles.add('Article ' + m[1]); });
return { json: {
  decision, risk_score, risk_tier,
  checks: { compliance: comp.compliant === true, security: sec.security_pass, privacy: priv.privacy_pass, permission: perm.permission_pass },
  datahub_context: dh,
  policy_aggregator: policyAgg,
  check_detail: {
    risk_reasons,
    compliance_reasoning: comp.reasoning || '',
    compliance_articles: comp.articles || [],
    security_flags: sec.security_flags || [],
    pii_found: priv.pii_found || {},
    permission_reasons: perm.permission_reasons || []
  },
  intent: intent.intent, category: intent.category, purpose: intent.purpose, summary: intent.summary,
  articles: Array.from(articles),
  reasons,
  agent_id: inp.agent_id, user_id: inp.user_id, action: inp.action,
  tool: inp.tool, confidence: inp.confidence, disclosed: inp.disclosed, human_in_loop: inp.human_in_loop,
  request: inp.request, decided_at: new Date().toISOString()
} };

// CONTROL ARM — no catalogue metadata.
// This is the deliberate counterfactual for the before/after experiment:
// the gateway must decide using the request text alone, with no DataHub
// context of any kind. Output shape matches the MCP arm exactly so the
// Decision Engine and Policy Aggregator run unmodified.
// Mode: "Run Once for Each Item".

const item = $input.item.json;

const ctx = {
  resolved: false,
  dataset: null,
  platform: null,
  action: null,
  owner: null,
  classification: null,
  tags: [],
  downstream_count: null,
  downstream_urns: [],
  urn: null,
  mcp_tools_used: [],
  metadata_source: 'none',
  note: 'control arm: catalogue metadata disabled',
};

return { json: { ...item, datahub_context: ctx } };

// Aggregator: read each policy helper directly, pick the strictest verdict.
// Strictness order: deny > human_review > approve

const rank = { approve: 0, human_review: 1, deny: 2 };
const nameByRank = { 0: 'approve', 1: 'human_review', 2: 'deny' };

// List every policy helper node here by its exact name on the canvas.
const policyNodes = [
  "Call 'policy_classification'",
  "Call 'policy_lineage'"
];

let worstRank = 0;
const policyResults = [];
const reasons = [];

for (const nodeName of policyNodes) {
  let p;
  try {
    p = $(nodeName).first().json;
  } catch (e) {
    continue; // node didn't run / not found — skip safely
  }
  if (!p || !p.verdict) continue;

  const v = String(p.verdict).toLowerCase();
  const r = (v in rank) ? rank[v] : 0;

  policyResults.push({ policy: p.policy || nodeName, verdict: v, reason: p.reason || '' });
  if (p.reason) reasons.push(p.reason);

  if (r > worstRank) worstRank = r;
}

const final_verdict = nameByRank[worstRank];

return { json: {
  source: 'policy_aggregator',
  final_verdict,
  policy_results: policyResults,
  reasons
} };

// Three demo scenarios — one click runs all three through the pipeline.
// Each becomes its own item, so the whole gateway evaluates each independently.

return [
  {
    json: {
      agent_id: "agent_007",
      user_id:  "user_123",
      action:   "delete",
      tool:     "database",
      request:  "delete the raw_customers table",
      target:   "raw_customers"
    }
  },
  {
    json: {
      agent_id: "agent_007",
      user_id:  "user_123",
      action:   "delete",
      tool:     "database",
      request:  "delete the raw_products table",
      target:   "raw_products"
    }
  },
  {
    json: {
      agent_id: "agent_099",
      user_id:  "user_456",
      action:   "delete",
      tool:     "database",
      request:  "delete the openbank.raw.transactions table",
      target:   "openbank.raw.transactions"
    }
  }
];

// Build one clean audit row per decision — only the columns that exist in raw.governance_audit.
const d = $input.item.json;
const dh = d.datahub_context || {};

return {
  json: {
    agent_id:         d.agent_id ?? null,
    user_id:          d.user_id ?? null,
    action:           d.action ?? null,
    target:           dh.dataset ?? null,
    classification:   dh.classification ?? null,
    downstream_count: String(dh.downstream_count ?? ''),
    decision:         d.decision ?? null,
    risk_score:       String(d.risk_score ?? ''),
    reasons:          JSON.stringify(d.reasons ?? [])
  }
};
